To check if an animation is in transition in Unity and perform actions accordingly, you'll work with the `Animator` component and its `IsInTransition()` method. Here's a clean, efficient approach:

**Basic Transition Check:**
```csharp
using UnityEngine;

public class AnimationTransitionHandler : MonoBehaviour
{
    private Animator animator;
    private int baseLayerIndex = 0;

    void Start()
    {
        animator = GetComponent<Animator>();
    }

    void Update()
    {
        if (animator.IsInTransition(baseLayerIndex))
        {
            // Currently transitioning between states
            HandleTransition();
        }
        else
        {
            // Stable state - safe to trigger new actions
            HandleStableState();
        }
    }

    void HandleTransition()
    {
        // Get transition info for precise control
        AnimatorTransitionInfo transInfo = animator.GetAnimatorTransitionInfo(baseLayerIndex);
        float progress = transInfo.normalizedTime;

        Debug.Log($"Transition progress: {progress:F2}");
    }

    void HandleStableState()
    {
        // Perform actions when not transitioning
    }
}
```

**Advanced: Waiting for Transition Completion**
```csharp
using System.Collections;
using UnityEngine;

public class TransitionAwaiter : MonoBehaviour
{
    private Animator animator;

    IEnumerator WaitForTransitionEnd(int layer, System.Action onComplete)
    {
        // Wait until transition starts
        yield return new WaitUntil(() => animator.IsInTransition(layer));

        // Wait until transition ends
        yield return new WaitWhile(() => animator.IsInTransition(layer));

        onComplete?.Invoke();
    }

    public void TriggerWithCallback(string triggerName, System.Action callback)
    {
        animator.SetTrigger(triggerName);
        StartCoroutine(WaitForTransitionEnd(0, callback));
    }
}
```

**Key Properties Available:**
- `IsInTransition(layerIndex)` — boolean check
- `GetAnimatorTransitionInfo(layerIndex).normalizedTime` — progress (0 to 1)
- `GetAnimatorTransitionInfo(layerIndex).duration` — transition length

