Here's a Python file implementing a basic grammar parser:

```python
class Grammar:
    def __init__(self):
        self.rules = {}
        self.start_symbol = None

    def add_rule(self, non_terminal, productions):
        """Add a production rule to the grammar."""
        if non_terminal not in self.rules:
            self.rules[non_terminal] = []
        if isinstance(productions, str):
            productions = [productions]
        self.rules[non_terminal].extend(productions)

    def set_start(self, symbol):
        """Set the start symbol for the grammar."""
        self.start_symbol = symbol

    def get_productions(self, non_terminal):
        """Get all productions for a non-terminal."""
        return self.rules.get(non_terminal, [])

    def is_terminal(self, symbol):
        """Check if a symbol is terminal."""
        return symbol not in self.rules

    def parse(self, tokens):
        """Simple recursive descent parsing attempt."""
        self.tokens = tokens
        self.pos = 0
        return self._parse_symbol(self.start_symbol)

    def _parse_symbol(self, symbol):
        if self.is_terminal(symbol):
            if self.pos < len(self.tokens) and self.tokens[self.pos] == symbol:
                self.pos += 1
                return True
            return False

        for production in self.get_productions(symbol):
            saved_pos = self.pos
            if self._parse_production(production):
                return True
            self.pos = saved_pos
        return False

    def _parse_production(self, production):
        symbols = production.split()
        for sym in symbols:
            if not self._parse_symbol(sym):
                return False
        return True


# Example usage
if __name__ == "__main__":
    g = Grammar()
    g.set_start('S')
    g.add_rule('S', 'NP VP')
    g.add_rule('NP', 'det noun')
    g.add_rule('VP', 'verb NP')

    tokens = ['det', 'noun', 'verb', 'det', 'noun']
    result = g.parse(tokens)
    print(f"Parse successful: {result}")
```

This implementation gives you the basics—rules, terminals, non-terminals, and a recursive descent parser. You can extend it with more sophisticated parsing algorithms.

