Here's a basic file system API implementation in Golang. This covers common operations like creating, reading, writing, and deleting files.

```go
package filesystem

import (
	"errors"
	"io"
	"os"
	"path/filepath"
)

// FileSystemAPI defines the interface for file operations
type FileSystemAPI interface {
	CreateFile(path string) error
	ReadFile(path string) ([]byte, error)
	WriteFile(path string, data []byte) error
	DeleteFile(path string) error
	ListDirectory(path string) ([]string, error)
	CreateDirectory(path string) error
}

// LocalFileSystem implements FileSystemAPI for local storage
type LocalFileSystem struct {
	basePath string
}

// NewLocalFileSystem creates a new local file system instance
func NewLocalFileSystem(basePath string) *LocalFileSystem {
	return &LocalFileSystem{basePath: basePath}
}

// CreateFile creates an empty file at the specified path
func (fs *LocalFileSystem) CreateFile(path string) error {
	fullPath := filepath.Join(fs.basePath, path)
	file, err := os.Create(fullPath)
	if err != nil {
		return err
	}
	return file.Close()
}

// ReadFile reads and returns the contents of a file
func (fs *LocalFileSystem) ReadFile(path string) ([]byte, error) {
	fullPath := filepath.Join(fs.basePath, path)
	return os.ReadFile(fullPath)
}

// WriteFile writes data to a file
func (fs *LocalFileSystem) WriteFile(path string, data []byte) error {
	fullPath := filepath.Join(fs.basePath, path)
	return os.WriteFile(fullPath, data, 0644)
}

// DeleteFile removes a file from the system
func (fs *LocalFileSystem) DeleteFile(path string) error {
	fullPath := filepath.Join(fs.basePath, path)
	return os.Remove(fullPath)
}

// ListDirectory returns contents of a directory
func (fs *LocalFileSystem) ListDirectory(path string) ([]string, error) {
	fullPath := filepath.Join(fs.basePath, path)
	entries, err := os.ReadDir(fullPath)
	if err != nil {
		return nil, err
	}

	var names []string
	for _, entry := range entries {
		names = append(names, entry.Name())
	}
	return names, nil
}

// CreateDirectory creates a new directory
func (fs *LocalFileSystem) CreateDirectory(path string) error {
	fullPath := filepath.Join(fs.basePath, path)
	return os.MkdirAll(fullPath, 0755)
}
```

This gives you a working foundation. You can extend it with more features like file copying or permission handling.

